{"op":"add","path":"/root","value":"composer"}
{"op":"add","path":"/elements/composer","value":{"type":"Composer","props":{"headline":"Your trip, planned day by day","lede":"Tell us where, when and who's going. Trip planner drafts the days and keeps them within your budget.","runLabel":"Plan my trip","columns":"2","notes":["A day-by-day plan, in order","Costs by category, with a total","A short overview of the trip","Tips for getting around"]},"on":{"press":[{"action":"validateForm"},{"action":"run"}]},"children":["group-where","group-who","group-feel","group-else"]}}
{"op":"add","path":"/elements/group-where","value":{"type":"FieldGroup","props":{"title":"Where & when"},"children":["trip-title","city","country","dates","must-see"]}}
{"op":"add","path":"/elements/trip-title","value":{"type":"Input","props":{"label":"Trip name","name":"title","placeholder":"Autumn in Lisbon","value":{"$bindState":"/inputs/request/title"},"checks":[{"type":"required","message":"Give the trip a name"}]},"children":[]}}
{"op":"add","path":"/elements/city","value":{"type":"Input","props":{"label":"City","name":"city","value":{"$bindState":"/inputs/request/stay/city"},"checks":[{"type":"required","message":"Add a city"}]},"children":[]}}
{"op":"add","path":"/elements/country","value":{"type":"Select","props":{"label":"Country","name":"country","options":["France","Italy","Japan","Portugal","Spain","United States"],"value":{"$bindState":"/inputs/request/stay/country"},"checks":[{"type":"required","message":"Choose a country"}]},"children":[]}}
{"op":"add","path":"/elements/dates","value":{"type":"DateRange","props":{"label":"Dates","from":{"$bindState":"/inputs/request/stay/arriving_on"},"to":{"$bindState":"/inputs/request/stay/leaving_on"}},"children":[]}}
{"op":"add","path":"/elements/must-see","value":{"type":"Chips","props":{"label":"Must-sees","placeholder":"Add a place and press Enter","value":{"$bindState":"/inputs/request/stay/must_see"}},"children":[]}}
{"op":"add","path":"/elements/group-who","value":{"type":"FieldGroup","props":{"title":"Who & budget"},"children":["travellers","with-children","budget","currency"]}}
{"op":"add","path":"/elements/travellers","value":{"type":"CompactList","props":{"label":"Travellers","items":{"$bindState":"/inputs/request/travellers"},"primary":"name","secondary":["age","dietary"],"addLabel":"Add a traveller"},"children":[]}}
{"op":"add","path":"/elements/with-children","value":{"type":"Switch","props":{"label":"Kids are coming","name":"with_children","checked":{"$bindState":"/inputs/request/with_children"}},"children":[]}}
{"op":"add","path":"/elements/budget","value":{"type":"NumberInput","props":{"label":"Total budget","name":"budget","value":{"$bindState":"/inputs/request/budget"}},"children":[]}}
{"op":"add","path":"/elements/currency","value":{"type":"Segmented","props":{"label":"Currency","name":"currency","options":["EUR","USD","GBP","JPY"],"value":{"$bindState":"/inputs/request/currency"}},"children":[]}}
{"op":"add","path":"/elements/group-feel","value":{"type":"FieldGroup","props":{"title":"The feel of it"},"children":["style","pace"]}}
{"op":"add","path":"/elements/style","value":{"type":"Segmented","props":{"label":"Mostly about","name":"style","options":["culture","food","nature","nightlife","family"],"value":{"$bindState":"/inputs/request/style"}},"children":[]}}
{"op":"add","path":"/elements/pace","value":{"type":"Segmented","props":{"label":"Pace","name":"pace","options":["slow","balanced","packed"],"value":{"$bindState":"/inputs/request/pace"}},"children":[]}}
{"op":"add","path":"/elements/group-else","value":{"type":"FieldGroup","props":{"title":"Anything else"},"children":["accessibility","notes","inspiration"]}}
{"op":"add","path":"/elements/accessibility","value":{"type":"Input","props":{"label":"Access needs","name":"accessibility","placeholder":"Step-free routes, fewer stairs…","value":{"$bindState":"/inputs/request/accessibility"}},"children":[]}}
{"op":"add","path":"/elements/notes","value":{"type":"Textarea","props":{"label":"Notes for the planner","name":"notes","rows":3,"value":{"$bindState":"/inputs/request/notes"}},"children":[]}}
{"op":"add","path":"/elements/inspiration","value":{"type":"MthdsField","props":{"path":"/inputs/inspiration","label":"An image that sets the mood"},"children":[]}}
